import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    static int L, C;
    static boolean[][] hasBlack;
    static boolean[][] isCandidate;
    static List<Integer>[] adj;
    static int[] match;
    static boolean[] visited;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        L = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());

        line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        int P = Integer.parseInt(line.trim());

        hasBlack = new boolean[L + 1][C + 1];
        for (int i = 0; i < P; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            st = new StringTokenizer(line);
            int r = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            hasBlack[r][c] = true;
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        isCandidate = new boolean[L + 1][C + 1];
        int totalCandidates = 0;

        for (int r = 1; r <= L; r++) {
            for (int c = 1; c <= C; c++) {
                if (hasBlack[r][c]) continue;
                boolean adjBlack = false;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && hasBlack[nr][nc]) {
                        adjBlack = true;
                        break;
                    }
                }
                if (adjBlack) {
                    isCandidate[r][c] = true;
                    totalCandidates++;
                }
            }
        }

        int[][] id = new int[L + 1][C + 1];
        int count = 0;
        for (int r = 1; r <= L; r++) {
            for (int c = 1; c <= C; c++) {
                if (isCandidate[r][c]) {
                    id[r][c] = count++;
                }
            }
        }

        adj = new ArrayList[count];
        for (int i = 0; i < count; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int r = 1; r <= L; r++) {
            for (int c = 1; c <= C; c++) {
                if (isCandidate[r][c] && (r + c) % 2 == 0) {
                    int u = id[r][c];
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && isCandidate[nr][nc]) {
                            int v = id[nr][nc];
                            adj[u].add(v);
                        }
                    }
                }
            }
        }

        match = new int[count];
        Arrays.fill(match, -1);
        visited = new boolean[count];

        int maxMatching = 0;
        for (int r = 1; r <= L; r++) {
            for (int c = 1; c <= C; c++) {
                if (isCandidate[r][c] && (r + c) % 2 == 0) {
                    Arrays.fill(visited, false);
                    if (dfs(id[r][c])) {
                        maxMatching++;
                    }
                }
            }
        }

        int maxWhite = totalCandidates - maxMatching;
        System.out.println(maxWhite);
    }

    static boolean dfs(int u) {
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                if (match[v] < 0 || dfs(match[v])) {
                    match[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}
